import path from 'path';
import { and, eq } from 'drizzle-orm';
import { openDurableDatabase, transaction, closeDatabase } from './database';
import { PROJECT_RUNTIME_SCHEMA } from './migrations';
import { projectRuntime } from './schema/projectRuntime';

type Database = Awaited<ReturnType<typeof openDurableDatabase>>;
export type ProjectRuntimeRecord = Omit<
  typeof projectRuntime.$inferSelect,
  'singleton'
>;
const RUNTIME_SINGLETON = 1;

export class ProjectRuntimeRecords {
  private constructor(private readonly db: Database) {}

  static async open(directory: string): Promise<ProjectRuntimeRecords> {
    return new ProjectRuntimeRecords(
      await openDurableDatabase({
        databasePath: path.join(directory, 'lifecycle.sqlite'),
        schema: PROJECT_RUNTIME_SCHEMA,
      }),
    );
  }

  transaction<T>(operation: () => T): T {
    return transaction(this.db, operation);
  }

  read(): ProjectRuntimeRecord | null {
    return (
      this.db
        .select({
          pid: projectRuntime.pid,
          token: projectRuntime.token,
          phase: projectRuntime.phase,
        })
        .from(projectRuntime)
        .where(eq(projectRuntime.singleton, RUNTIME_SINGLETON))
        .get() ?? null
    );
  }

  assign(record: ProjectRuntimeRecord): void {
    this.db
      .insert(projectRuntime)
      .values({ singleton: RUNTIME_SINGLETON, ...record })
      .onConflictDoUpdate({ target: projectRuntime.singleton, set: record })
      .run();
  }

  transfer({ token, pid, phase }: ProjectRuntimeRecord): void {
    this.db
      .update(projectRuntime)
      .set({ pid, phase })
      .where(eq(projectRuntime.token, token))
      .run();
  }

  release(token: string): void {
    this.db.delete(projectRuntime).where(eq(projectRuntime.token, token)).run();
  }

  releaseReady(pid: number): void {
    this.db
      .delete(projectRuntime)
      .where(
        and(eq(projectRuntime.pid, pid), eq(projectRuntime.phase, 'starting')),
      )
      .run();
  }

  close(): void {
    closeDatabase(this.db);
  }
}
